  el.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-b-zoom]')){ui.zoom=t.value;layout();return}const path=t.dataset.bSet;if(!path)return;if(t.tagName==='SELECT'){set(path,t.value);return}if(t.type==='checkbox'){set(path,t.checked);return}if(t.type==='range'||t.type==='color'||t.dataset.hex!==void 0)softRight()});
