  el.addEventListener('keydown',e=>{const t=e.target;if(t.matches('[data-b-layer]')){const items=$$('[data-b-layer]'),i=items.indexOf(t);if(e.altKey&&/^Arrow(Up|Down)$/.test(e.key)){e.preventDefault();act(e.key==='ArrowUp'?'up':'down');requestAnimationFrame(()=>$('[data-b-layer].on')?.focus());return}if(/^Arrow(Up|Down)$/.test(e.key)){e.preventDefault();const n=items[Math.max(0,Math.min(items.length-1,i+(e.key==='ArrowUp'?-1:1)))];select(n.dataset.bLayer);n.focus();return}if(e.key==='Enter'||e.key===' '){e.preventDefault();select(t.dataset.bLayer)}}});
