 // Pointer-driven sorting (mouse, pen and touch) for layers and list rows.
 function sortable(list,itemSel,onDrop){if(!list)return;list.addEventListener('pointerdown',e=>{const item=e.target.closest(itemSel);if(!item||e.button!==0)return;const grip=e.target.closest('[data-grip]');if(!grip&&e.target.closest('input,button,textarea,select'))return;if(e.pointerType==='touch'&&!grip)return;
  const items=[...list.querySelectorAll(itemSel)],from=items.indexOf(item),y0=e.clientY;let started=false,to=from;const line=document.createElement('div');line.className='sort-line';
  const move=ev=>{if(!started){if(Math.abs(ev.clientY-y0)<5)return;started=true;item.classList.add('sorting');list.append(line);el.dataset.dragged='1'}ev.preventDefault();to=items.length;for(let i=0;i<items.length;i++){const r=items[i].getBoundingClientRect();if(ev.clientY<r.top+r.height/2){to=i;break}}const ref=items[to]||items[items.length-1],lr=list.getBoundingClientRect(),rr=ref.getBoundingClientRect();line.style.top=((items[to]?rr.top:rr.bottom)-lr.top+list.scrollTop-2)+'px';const sc=list.closest('.panel-scroll');if(sc){const sr=sc.getBoundingClientRect();if(ev.clientY<sr.top+30)sc.scrollTop-=8;if(ev.clientY>sr.bottom-30)sc.scrollTop+=8}};
  const up=()=>{removeEventListener('pointermove',move);removeEventListener('pointerup',up);removeEventListener('pointercancel',up);line.remove();item.classList.remove('sorting');if(started){let dest=to>from?to-1:to;if(dest!==from)onDrop(from,dest);setTimeout(()=>delete el.dataset.dragged,0)}};
  addEventListener('pointermove',move,{passive:false});addEventListener('pointerup',up);addEventListener('pointercancel',up)})}
