 function sortListEditors(){$$('[data-b-list]').forEach(box=>sortable(box,'.le-row',(from,to)=>{const rows=$$('.le-row',box);const r=rows[from];box.insertBefore(r,rows[to>from?to+1:to]||null);if(to>from&&!rows[to+1])box.append(r);set('prop.'+box.dataset.bList,listValue(box));renderRight()}))}
 // Dragging a palette card onto the canvas: the iframe draws the drop line and replies with the target position.
 function paletteDrag(e){const card=e.target.closest('[data-b-add]');if(!card||e.button!==0)return;const type=card.dataset.bAdd,x0=e.clientX,y0=e.clientY;let ghost=null,over=false;if(e.pointerType!=='touch'){e.preventDefault();try{card.setPointerCapture(e.pointerId)}catch{}}
  const move=ev=>{if(!ghost){if(Math.hypot(ev.clientX-x0,ev.clientY-y0)<6)return;ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=`<span>${CAT_GLYPH[BLOCKS.find(b=>b.id===type).category]||'✳'}</span>${esc(BLOCKS.find(b=>b.id===type).name)}`;document.body.append(ghost);el.classList.add('is-dragging')}
   ghost.style.translate=`${ev.clientX+12}px ${ev.clientY+12}px`;const fr=activeFrame().getBoundingClientRect(),st=$('[data-b-stage]').getBoundingClientRect();const inside=ev.clientX>st.left&&ev.clientX<st.right&&ev.clientY>st.top&&ev.clientY<st.bottom;
   if(inside){over=true;ghost.classList.add('ok');post({type:'dragover',y:(ev.clientY-fr.top)/canvas.scale,label:'放入「'+BLOCKS.find(b=>b.id===type).name+'」'})}else if(over){over=false;ghost.classList.remove('ok');post({type:'dragleave'})}};
  const up=ev=>{card.removeEventListener('pointermove',move);card.removeEventListener('pointerup',up);card.removeEventListener('pointercancel',up);if(!ghost)return;ghost.remove();el.classList.remove('is-dragging');el.dataset.dragged='1';setTimeout(()=>delete el.dataset.dragged,0);if(over&&ev.type==='pointerup'){if(!P().blocks.some(b=>!b.hidden))insertBlock(type,null);else post({type:'drop',blockType:type})}else post({type:'dragleave'})};
  card.addEventListener('pointermove',move);card.addEventListener('pointerup',up);card.addEventListener('pointercancel',up)}

 return {render,refresh,mounted,select:id=>select(id),applyStyle(patch){const b=sel();if(!b)return false;ctx.mutate(()=>{b.style=normalizeBlockStyle({...b.style,...patch})});return true},applyEffects(patch){ctx.mutate(()=>{P().effects=normalizeEffects({...P().effects,...patch})})},hasSelection:()=>!!sel(),selectedName:()=>sel()?blockLabel(sel()):''};
