// ---------- Effects lab: a gallery of every motion and surface option, applied straight to the selected block ----------
export function renderFxLab(root,{theme,icon,selectedName,toast}){const t=normalizeTheme(theme),name=selectedName();
 const vars=`--accent:${t.accent};--accent-2:${t.accent2};--ink:${t.ink};--bg:${t.bg};--surface:${t.surface};--muted:${t.muted};--line:color-mix(in srgb,${t.ink} 14%,transparent);--tint:color-mix(in srgb,${t.accent} 10%,${t.surface});--radius:${Math.min(t.radius,22)}px;--button-ink:#fff`;
 const card=(group,key,label,stage,desc='')=>`<article class="fxl-card" data-fxl-group="${group}"><div class="fxl-stage" data-fxl-stage>${stage}</div><div class="fxl-meta"><div><b>${esc(label)}</b><small>${esc(desc||key)}</small></div><div class="fxl-actions"><button type="button" class="mini-btn ghost" data-fxl-replay title="重播">▶</button><button type="button" class="mini-btn" data-fxl-apply="${group}" data-v="${key}" ${name||group==='page'?'':'disabled'}>应用</button></div></div></article>`;
 const enterStage=k=>`<div class="fxl-enter" data-enter="${k}" data-stagger style="--fx-step:110ms;--fx-d:800ms"><i class="fx-t" style="--fx-i:0"></i><i class="fx-t" style="--fx-i:1"></i><i class="fx-t" style="--fx-i:2"></i></div>`;
 const groups=[
  ['enter','入场动效','模块进入视野时的出场方式。悬停或点击 ▶ 重播。',FX_OPTIONS.enter.slice(1).map(([k,l])=>card('enter',k,l,enterStage(k)))],
  ['hover','悬停效果','让卡片对指针作出回应。把鼠标移到卡片上。',FX_OPTIONS.hover.slice(1).map(([k,l])=>card('hover',k,l,`<div class="fxl-hover" data-hover="${k}"><div class="panel"><b>Hover</b><small>移上来看看</small></div></div>`))],
  ['text','标题特效','给主标题一点个性。',FX_OPTIONS.text.slice(1).map(([k,l])=>card('text',k,l,`<div class="fxl-text" data-text="${k}"><div class="section-heading"><h2>好设计，会发光。</h2></div></div>`))],
  ['pattern','背景特效','放在模块内容后面的氛围层。',FX_OPTIONS.pattern.slice(1).map(([k,l])=>card('pattern',k,l,`<div class="fxl-bgstage"><div class="fx-bg" data-fx-bg="${k}" style="--fx-po:85">${['aurora','stars','waves','beams'].includes(k)?'<i></i><i></i><i></i>':''}</div><b>Atmosphere</b></div>`))],
  ['loop','循环动效','让装饰元素保持轻微的生命感。',FX_OPTIONS.loop.slice(1).map(([k,l])=>card('loop',k,l,`<div class="fxl-loop" data-loop="${k}"><div class="panel fx-l" style="--fx-li:0">✳</div><div class="panel fx-l" style="--fx-li:1">◎</div></div>`))]
 ];
 root.innerHTML=`<div class="fx-lab" style="${vars}"><div class="page-eyebrow"><i></i>MOTION &amp; EFFECTS LAB</div><div class="page-heading fxl-heading"><div><h1>让页面，<em>动起来。</em></h1><p>${FX_OPTIONS.enter.length-1+FX_OPTIONS.hover.length-1+FX_OPTIONS.text.length-1+FX_OPTIONS.pattern.length-1+FX_OPTIONS.loop.length-1} 种原创动效与氛围，全部用原生 CSS 与少量 JavaScript 实现，导出后无需任何依赖。预览使用当前项目主题「${esc(t.name)}」。</p></div><div class="fxl-target">${name?`<small>将应用到</small><b>${esc(name)}</b><button class="mini-btn ghost" data-view="builder">回到拼装台 ↗</button>`:`<small>还没有选中模块</small><b>先在拼装台选择一个模块</b><button class="mini-btn" data-view="builder">去拼装台 ↗</button>`}</div></div>
 <nav class="fxl-nav" aria-label="特效分类">${groups.map(([g,n,,c])=>`<a href="#fxl-${g}">${n}<small>${c.length}</small></a>`).join('')}<a href="#fxl-page">页面特效<small>6</small></a></nav>
 ${groups.map(([g,n,d,c])=>`<section class="fxl-group" id="fxl-${g}"><header><h2>${n}</h2><p>${d}</p></header><div class="fxl-grid">${c.join('')}</div></section>`).join('')}
 <section class="fxl-group" id="fxl-page"><header><h2>页面特效</h2><p>作用于整个页面，在拼装台「页面」面板中也能调整。</p></header><div class="fxl-grid fxl-page">${[['progress','滚动进度条','顶部细条随阅读进度增长'],['backTop','回到顶部','滚动后出现的圆形按钮'],['grain','胶片颗粒','全局细腻噪点质感'],['cursor:glow','柔光光标','跟随指针的柔和光晕'],['cursor:ring','光圈光标','带拖尾的描边圆环'],['intro:curtain','开场幕布','载入时品牌色幕布上升']].map(([k,l,d])=>`<article class="fxl-card"><div class="fxl-stage fxl-page-art" data-k="${k}"><i></i><span>✳</span></div><div class="fxl-meta"><div><b>${l}</b><small>${d}</small></div><div class="fxl-actions"><button type="button" class="mini-btn" data-fxl-apply="page" data-v="${k}">开启</button></div></div></article>`).join('')}</div></section></div>`;
 const replay=st=>{const n=st.querySelector('[data-enter]');if(n){n.classList.remove('fx-replay');void n.offsetWidth;n.classList.add('fx-replay')}st.querySelectorAll('[data-text=split] h2').forEach(h=>{const p=h.parentElement.parentElement;p.classList.remove('fx-replay');void p.offsetWidth;p.classList.add('fx-replay')})};
 root.querySelectorAll('[data-text=split] h2').forEach(h=>{let c=0;h.innerHTML=[...h.textContent].map(ch=>`<span class="fx-ch" style="--c:${c++}">${esc(ch)}</span>`).join('')});
 const io=new IntersectionObserver(l=>l.forEach(x=>{if(x.isIntersecting){replay(x.target);io.unobserve(x.target)}}),{threshold:.4});root.querySelectorAll('[data-fxl-stage]').forEach(s=>io.observe(s));
 root.querySelector('.fx-lab').addEventListener('pointerenter',e=>{const s=e.target.closest?.('[data-fxl-stage]');if(s&&s.querySelector('[data-enter]'))replay(s)},true);
 root.querySelector('.fx-lab').addEventListener('pointermove',e=>{const c=e.target.closest('[data-hover=tilt] .panel');if(c){const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;c.style.setProperty('--rx',((.5-y)*14)+'deg');c.style.setProperty('--ry',((x-.5)*16)+'deg');c.style.setProperty('--gx',x*100+'%');c.style.setProperty('--gy',y*100+'%')}const bg=e.target.closest('.fxl-bgstage');if(bg){const r=bg.getBoundingClientRect();bg.style.setProperty('--px',(e.clientX-r.left)+'px');bg.style.setProperty('--py',(e.clientY-r.top)+'px')}});
 root.querySelector('.fx-lab').addEventListener('click',e=>{const r=e.target.closest('[data-fxl-replay]');if(r)replay(r.closest('.fxl-card').querySelector('[data-fxl-stage]'))});
 return {replay};
}
